function addLog(type,text){state.log.unshift({type,text,date:dateString(),time:state.date.hour.toString().padStart(2,'0')+':00'});state.log=state.log.slice(0,30)}
function dateString(){return MONTHS[state.date.month]+' '+String(state.date.day).padStart(2,'0')+', '+state.date.year}
function tick(){if(state.paused)return;advanceStep()}
function advanceStep(){state.step++;state.date.hour+=6;if(state.date.hour>=24){state.date.hour=0;state.date.day++;let days=new Date(state.date.year,state.date.month+1,0).getDate();if(state.date.day>days){state.date.day=1;state.date.month++;if(state.date.month>11){state.date.month=0;state.date.year++;newYear()}}}updateWeather();render();drawMap()}
function newYear(){state.archive.push({year:state.date.year-1,named:state.named,hurricanes:state.hurricanes,landfalls:state.landfalls,damage:state.damage});state.named=state.hurricanes=state.landfalls=state.damage=0;state.nameIndex=0;addLog('good','January 1. A new calendar year begins; the global watch continues.');$('#yearBadge').textContent='SEASON '+state.date.year}
function inBounds(lon,lat){return lon>=basin.bounds[0]&&lon<=basin.bounds[1]&&lat>=basin.bounds[2]&&lat<=basin.bounds[3]}
function spawnDisturbance(){let [x0,x1,y0,y1]=basin.bounds, lon=x0+rand()*(x1-x0),lat=y0+rand()*(y1-y0);if(basin.id==='atl'||basin.id==='epac')lat=8+rand()*19;else if(basin.id==='wpac')lat=5+rand()*20;else if(basin.id==='ni')lat=5+rand()*16;else lat=-9-rand()*14;
