function nameStorm(s){if(s.name)return;let base=basin.names[state.nameIndex%basin.names.length];state.nameIndex++;let name=base;if(state.retired[base]){let key=base[0].toUpperCase(),i=state.replacementIndex[key]||0,choices=RETIRE_REPLACEMENTS[key]||['New '+key];name=choices[i%choices.length];state.replacementIndex[key]=i+1;addLog('good',base+' was retired from the basin list. '+name+' replaces it, preserving the initial '+key+'.')}s.name=name;s.status='Tropical Storm';state.named++;addLog('good','Tropical Storm '+s.name+' has been named with sustained winds of '+s.wind+' kt.')}
function updateWeather(){let d=state.date,m=d.month,active=isSeasonMonth(m),chance=active?.012:.0017;if(state.storms.length<3&&rand()<chance)spawnDisturbance();for(let i=state.storms.length-1;i>=0;i--){let s=state.storms[i];s.age++;let warm=basin.temp+(active?1:0),shear=rand();let change=(warm>27?1.8:0.6)+(rand()-.46)*12-(shear>.82?8:0);if(s.lat<0)change+=(s.lat<-25?-5:1);s.wind=clamp(Math.round(s.wind+change),0,160);if(s.wind<1){dissipate(s,i,'The disturbance dissipated over cooler water.');continue}if(s.wind>=34&&!s.name)nameStorm(s);if(s.wind>=64&&s.wind<96&&s.status!=='Hurricane'){s.status='Hurricane';state.hurricanes++;addLog('impact',''+(s.name||'A system')+' has strengthened to hurricane force, '+s.wind+' kt.')}else if(s.wind>=96&&s.status!=='Major Hurricane'){if(s.status!=='Hurricane')state.hurricanes++;s.status='Major Hurricane';addLog('impact',''+(s.name||'A system')+' is now a major hurricane at '+s.wind+' kt.')}else if(s.name&&s.wind<64)s.status='Tropical Storm';
let dir=(s.lat>=0?1:-1),west=s.age<9?-1:1;s.lon+=west*(.9+rand()*1.25);s.lat+=dir*(.12+rand()*.45)+(s.age>12?dir*.15:0);s.lon=clamp(s.lon,basin.bounds[0],basin.bounds[1]);s.lat=clamp(s.lat,basin.bounds[2],basin.bounds[3]);if(s.track.length===0||Math.hypot(s.lon-s.track[s.track.length-1][0],s.lat-s.track[s.track.length-1][1])>.1)s.track.push([s.lon,s.lat]);if(s.track.length>30)s.track.shift();
