if(s.age>20||s.wind<23||(s.age>10&&s.lat===basin.bounds[2]||s.age>10&&s.lat===basin.bounds[3])){dissipate(s,i,s.name?s.name+' has weakened and dissipated.':'The disturbance dissipated.')}}
for(let s of state.storms){s.forecast=[];let lon=s.lon,lat=s.lat,dir=lat>=0?1:-1;for(let j=1;j<=6;j++){lon=clamp(lon+(s.age<9?-1.5:1.5),basin.bounds[0],basin.bounds[1]);lat=clamp(lat+dir*.42,basin.bounds[2],basin.bounds[3]);s.forecast.push([lon,lat])}}}
function dissipate(s,i,msg){state.storms.splice(i,1);if(selectedId===s.id)selectedId=null;if(s.name)addLog('',msg)}
function isLand(lon,lat){for(let poly of LAND)if(pointPoly(lon,lat,poly))return true;return false}
function pointPoly(x,y,p){let inside=false;for(let i=0,j=p.length-1;i<p.length;j=i++){let a=p[i],b=p[j];if(((a[1]>y)!==(b[1]>y))&&(x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]))inside=!inside}return inside}
function nearestCity(lon,lat){return nearestCityDistance(lon,lat).name}function nearestCityDistance(lon,lat){let best={d:999,name:'coastal communities'};for(let c of basin.cities){let d=Math.hypot((c[0]-lon)*Math.cos(lat*Math.PI/180),c[1]-lat);if(d<best.d)best={d,name:c[2]}}return best}
function formatCoord(lat,lon){return Math.abs(lat).toFixed(1)+'°'+(lat>=0?'N':'S')+', '+Math.abs(lon>180?lon-360:lon).toFixed(1)+'°'+(lon>180?'W':'E')}

