function formatCoord(lat,lon){let signed=lon>180?lon-360:lon;return Math.abs(lat).toFixed(1)+'°'+(lat>=0?'N':'S')+', '+Math.abs(signed).toFixed(1)+'°'+(signed<0?'W':'E')}
function category(w){if(w>=137)return 'Cat 5';if(w>=113)return 'Cat 4';if(w>=96)return 'Cat 3';if(w>=83)return 'Cat 2';if(w>=64)return 'Cat 1';return w>=34?'Tropical Storm':'Disturbance'}
function render(){let d=state.date;$('#dateLabel').textContent=MONTHS[d.month]+' '+String(d.day).padStart(2,'0');$('#timeLabel').textContent=String(d.hour).padStart(2,'0')+':00 UTC';$('#clock').textContent='UTC '+String(d.hour).padStart(2,'0')+':00';$('#seasonProgress').textContent='DAY '+Math.floor((new Date(d.year,d.month,d.day)-new Date(d.year,0,0))/86400000)+' / 365';$('#namedCount').textContent=state.named;$('#hurricaneCount').textContent=state.hurricanes;$('#landfallCount').textContent=state.landfalls;$('#damageCount').textContent=fmtMoney(state.damage);$('#trust').textContent=state.trust+'%';$('#funds').textContent=fmtMoney(state.funds);$('#systemCount').textContent=state.storms.length+' TRACKED';$('#stormList').innerHTML=state.storms.length?state.storms.map(s=>`<button class="storm-chip ${s.id===selectedId?'selected':''}" data-id="${s.id}"><b>${s.name||'Invest '+String(s.id).padStart(2,'0')}</b><span>${category(s.wind)} · <i class="intensity">${s.wind} kt</i></span></button>`).join(''):'<div class="empty">No active disturbances. The ocean is being watched.</div>';
$('#stormList').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedId=+b.dataset.id;render();drawMap()});$('#log').innerHTML=state.log.map(e=>`<div class="logitem ${e.type}"><span class="logtime">${e.date.slice(0,6)} ${e.time}</span><i class="logmark"></i><span>${e.text}</span></div>`).join('');renderSelected();$('#toggle').innerHTML=state.paused?'▶ &nbsp;Resume':'Ⅱ &nbsp;Pause';document.querySelectorAll('.speed button').forEach(b=>b.classList.toggle('active',+b.dataset.speed===speed))}
function renderSelected(){let s=state.storms.find(x=>x.id===selectedId);if(!s){$('#stormAge').textContent='—';$('#selectedPanel').innerHTML='<div class="empty">Select an active storm on the map or in the systems list.</div>';return}$('#stormAge').textContent='ADVISORY '+String(s.age).padStart(2,'0');let close=nearestCityDistance(s.lon,s.lat),can=s.name&&!s.evacuated&&close.d<24&&state.funds>=120000000;$('#selectedPanel').innerHTML=`<div class="selection"><div class="selected-name"><strong>${s.name||'Invest '+String(s.id).padStart(2,'0')}</strong><span class="category">${category(s.wind)}</span></div><div class="storm-data"><div class="data"><span>Max sustained</span><strong>${s.wind} kt · ${Math.round(s.wind*1.15078)} mph</strong></div><div class="data"><span>Min pressure</span><strong>${Math.round(1013-s.wind*.58)} hPa</strong></div><div class="data"><span>Position</span><strong>${formatCoord(s.lat,s.lon)}</strong></div><div class="data"><span>Nearest coast</span><strong>${close.name}</strong></div></div>${s.landfall?'<div class="advisory">Coastal impact recorded. Estimated losses: '+fmtMoney(s.damage)+(s.retired?' · NAME RETIRED':'')+'</div>':`<button class="action" id="evacuate" ${can?'':'disabled'}>◈ &nbsp; ${s.evacuated?'Evacuation order issued':'Issue coastal evacuation'}<small>${s.evacuated?'Public alert active · projected impact reduced':can?'Fund high-risk coastal preparedness · $120M':'Available when a named system threatens the coast'}</small></button>`}${s.advisory&&!s.landfall?'<div class="advisory">Coastal watch: '+close.name+' is within the forecast envelope. Review evacuation guidance.</div>':''}</div>`;let btn=$('#evacuate');if(btn)btn.onclick=()=>issueEvacuation(s)}
function issueEvacuation(s){if(s.evacuated||state.funds<120000000)return;s.evacuated=true;s.evacLevel=1;state.funds-=120000000;state.trust=clamp(state.trust+1,0,100);addLog('good','Coastal evacuation order issued for '+nearestCity(s.lon,s.lat)+'. Response fund committed: $120M.');render();drawMap()}

