function issueEvacuation(s){if(s.evacuated||state.funds<120000000)return;s.evacuated=true;s.evacLevel=1;state.funds-=120000000;state.trust=clamp(state.trust+1,0,100);addLog('good','Coastal evacuation order issued for '+nearestCity(s.lon,s.lat)+'. Response fund committed: $120M.');render();drawMap()}
function resizeCanvas(){let r=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawMap()}
function project(lon,lat){let w=canvas.clientWidth,h=canvas.clientHeight,[x0,x1,y0,y1]=basin.bounds,pad=30,baseW=w-pad*2,baseH=h-pad*2,fit=Math.min(baseW/(x1-x0),baseH/(y1-y0)),f=fit*scale,cx=w/2+offsetX,cy=h/2+offsetY;return [cx+(lon-(x0+x1)/2)*f,cy- (lat-(y0+y1)/2)*f]}
function drawMap(){if(!basin||!canvas.clientWidth)return;let w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#0b3040');g.addColorStop(.52,'#0a2939');g.addColorStop(1,'#092433');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);let [x0,x1,y0,y1]=basin.bounds;ctx.save();ctx.strokeStyle='#4d899055';ctx.lineWidth=1;ctx.setLineDash([2,6]);for(let lon=Math.ceil(x0/10)*10;lon<x1;lon+=10){let a=project(lon,y0),b=project(lon,y1);ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke()}for(let lat=Math.ceil(y0/10)*10;lat<y1;lat+=10){let a=project(x0,lat),b=project(x1,lat);ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke()}ctx.setLineDash([]);
for(let poly of LAND){let first=project(poly[0][0],poly[0][1]);if(first[0]<-100||first[0]>w+100||first[1]<-100||first[1]>h+100)continue;ctx.beginPath();ctx.moveTo(...first);for(let pt of poly.slice(1)){let q=project(pt[0],pt[1]);ctx.lineTo(q[0],q[1])}ctx.closePath();ctx.fillStyle='#36544f';ctx.fill();ctx.strokeStyle='#79a28b';ctx.lineWidth=1.15;ctx.stroke();ctx.save();ctx.clip();ctx.strokeStyle='#8caa8c20';ctx.lineWidth=1;for(let i=0;i<8;i++){let y=first[1]+i*9;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y+14);ctx.stroke()}ctx.restore()}
ctx.font='500 10px DM Mono,monospace';ctx.fillStyle='#d3e6dc88';for(let c of basin.cities){let p=project(c[0],c[1]);ctx.beginPath();ctx.arc(p[0],p[1],2,0,Math.PI*2);ctx.fillStyle='#d2e7d8';ctx.fill();ctx.fillStyle='#d3e6dc99';ctx.fillText(c[2].toUpperCase(),p[0]+5,p[1]-5)}ctx.restore();let label=basin.name.toUpperCase();ctx.font='500 12px DM Mono,monospace';ctx.fillStyle='#b0d7dc22';ctx.textAlign='center';ctx.fillText(label,w/2,h*.54);ctx.textAlign='left';
for(let s of state.storms){if(s.forecast?.length){let points=[project(s.lon,s.lat),...s.forecast.map(p=>project(...p))];ctx.beginPath();for(let i=0;i<points.length;i++){let spread=7+i*2.7,q=[points[i][0]+spread,points[i][1]-spread*.45];if(i===0)ctx.moveTo(...q);else ctx.lineTo(...q)}for(let i=points.length-1;i>=0;i--){let spread=7+i*2.7,q=[points[i][0]-spread,points[i][1]+spread*.45];ctx.lineTo(...q)}ctx.closePath();ctx.fillStyle='#69d9ce17';ctx.fill();ctx.strokeStyle='#9bd9d055';ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([])}if(s.track.length>1){ctx.beginPath();s.track.forEach((p,i)=>{let q=project(...p);if(i===0)ctx.moveTo(...q);else ctx.lineTo(...q)});ctx.strokeStyle=s.id===selectedId?'#b9eb6b':'#9edbd2';ctx.lineWidth=s.id===selectedId?2.4:1.6;ctx.setLineDash([5,4]);ctx.stroke();ctx.setLineDash([])}let p=project(s.lon,s.lat),color=s.wind>=64?'#ff8b79':'#62e0d0';ctx.beginPath();ctx.arc(p[0],p[1],s.id===selectedId?9:7,0,Math.PI*2);ctx.fillStyle='#0a1c28';ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.arc(p[0],p[1],2.6,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.font='700 11px DM Sans,sans-serif';let txt=s.name||'INV '+String(s.id).padStart(2,'0'),tw=ctx.measureText(txt).width;ctx.fillStyle='#061722dc';ctx.beginPath();ctx.roundRect(p[0]+12,p[1]-12,tw+13,22,5);ctx.fill();ctx.fillStyle='#e3f3ef';ctx.fillText(txt,p[0]+18,p[1]+3)}
ctx.strokeStyle='#75a6a044';ctx.lineWidth=1;ctx.strokeRect(0,0,w,h)}
function canvasHit(e){let r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,hit=null,best=20;for(let s of state.storms){let p=project(s.lon,s.lat),d=Math.hypot(p[0]-x,p[1]-y);if(d<best){best=d;hit=s}}return hit}
